from html.parser import HTMLParser
from pathlib import Path


class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.skip = 0
        self.in_content = 0
        self.capture = False
        self.tags = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        cls = attrs.get("class", "")
        if tag in {"script", "style"}:
            self.skip += 1
        if "entry-content" in cls or "textwidget" in cls:
            self.in_content += 1
        self.tags.append((tag, cls))
        if tag == "a" and self.in_content:
            href = attrs.get("href")
            if href:
                self.parts.append(f"[A:{href}]")
        if tag == "img":
            src = attrs.get("data-src") or attrs.get("src") or ""
            alt = attrs.get("alt") or ""
            title = attrs.get("title") or ""
            if "logo" not in src.lower() and "svg+xml" not in src:
                self.parts.append(f"[IMG alt={alt!r} title={title!r} src={src}]")

    def handle_endtag(self, tag):
        if tag in {"script", "style"} and self.skip:
            self.skip -= 1
        if self.tags:
            t, cls = self.tags.pop()
            if "entry-content" in cls or "textwidget" in cls:
                self.in_content = max(0, self.in_content - 1)
        if tag in {"p", "h1", "h2", "h3", "h4", "li", "br", "div"} and self.in_content:
            self.parts.append("\n")

    def handle_data(self, data):
        if self.skip or not self.in_content:
            return
        text = data.strip()
        if text:
            self.parts.append(text + " ")


