def fetch(url: str):
    print("CDX", url)
    req = urllib.request.Request(url, headers=UA)
    try:
        with urllib.request.urlopen(req, timeout=180) as resp:
            data = json.loads(resp.read().decode("utf-8", errors="ignore"))
    except Exception as e:
        print(" CDX failed", type(e).__name__, e)
        return []
    print(" rows", len(data))
    return data


def main() -> None:
    combined = []
    seen = set()
    for url in URLS:
        rows = fetch(url)
        if not rows:
            continue
        header, body = rows[0], rows[1:]
        if not combined:
            combined.append(header)
        for row in body:
            key = (row[0], row[1], row[4] if len(row) > 4 else "")
            if key in seen:
                continue
            seen.add(key)
            combined.append(row)
    out = API / "cdx.json"
    out.write_text(json.dumps(combined), encoding="utf-8")
    print("unique rows", max(0, len(combined) - 1), "->", out)

