def merge_text(existing: Optional[str], incoming: Optional[str]) -> Optional[str]:
    if not incoming:
        return existing
    if not existing:
        return incoming
    have = existing.lower()
    extra = []
    for piece in incoming.split(" | "):
        p = clean_piece(piece)
        if p and p.lower() not in have:
            extra.append(p)
    if not extra:
        return existing
    return existing + " | " + " | ".join(extra)


