@'
#!/usr/bin/env python3
"""STRICT web contact fill: kennel-matching websites only; email/phone from kennel-context snippets."""
from __future__ import annotations

import re
import time
from urllib.parse import urlparse

from ddgs import DDGS
from enrich_jrtcabreeders import apply_web_facts, get_conn
from scrape_jrtcabreeders import EMAIL_RE, PHONE_RE

STATE_RE = re.compile(
    r"\b([A-Z][a-zA-Z]+(?:\s[A-Z][a-zA-Z]+)?),\s*([A-Z]{2})\b(?:\s+(\d{5}(?:-\d{4})?))?"
)


def kennel_fold(name: str) -> str:
    return re.sub(r"[^a-z0-9]", "", (name or "").lower())


def host(url: str) -> str:
    try:
        return urlparse(url).netloc.lower().removeprefix("www.")
    except Exception:
        return ""


def website_for_kennel(kennel: str, urls: list[str]) -> str | None:
    kf = kennel_fold(kennel)
    if len(kf) < 6:
        return None
    for u in urls:
        u = u.rstrip(".,);]")
        h = host(u).replace("-", "").replace(".", "")
        if kf[:8] in h or kf in h:
            # reject social / marketplaces even if name match
            hn = host(u)
            if any(x in hn for x in (
                "facebook", "instagram", "youtube", "ebay", "craigslist",
                "wikipedia", "yellowpages", "whitepages", "mylife", "bizapedia",
                "contactout", "linkedin", "puppies.com", "dogster",
            )):
                continue
            return u[:500]
    return None


def facts_from_results(kennel: str, results: list[dict]) -> dict:
    kf = kennel_fold(kennel)
    facts = {}
    urls = []
    for r in results:
        title = r.get("title") or ""
        body = r.get("body") or ""
        href = (r.get("href") or "").strip()
        if href:
            urls.append(href)
        blob = f"{title} {body}"
        # require kennel token in snippet for contact extraction
        blob_fold = re.sub(r"[^a-z0-9]", "", blob.lower())
        if kf[:6] not in blob_fold and kennel.lower() not in blob.lower():
            continue
        if "email" not in facts:
            em = EMAIL_RE.search(blob)
            if em and not em.group(0).lower().endswith(("@example.com", "@sentry.io")):
                facts["email"] = em.group(0)
        if "phone" not in facts:
            ph = PHONE_RE.search(blob)
            if ph:
                facts["phone"] = ph.group(0)
        if "city" not in facts:
            sm = STATE_RE.search(blob)
            if sm:
                facts["city"] = sm.group(1)
                facts["state"] = sm.group(2)
                if sm.group(3):
                    facts["postal"] = sm.group(3)
    web = website_for_kennel(kennel, urls)
    if web:
        facts["website"] = web
    return facts


def main() -> None:
    conn = get_conn()
    conn.autocommit = False
    cur = conn.cursor()
    cur.execute(
        """
        SELECT BreederID, KennelName, OwnerName, City, Website, Email, Phone
        FROM sResults.Breeder
        WHERE KennelName IS NOT NULL AND LEN(KennelName) >= 5 AND KennelName NOT LIKE '%<%'
          AND (
                Website IS NULL OR Website = ''
             OR Email IS NULL OR Email = ''
             OR Phone IS NULL OR Phone = ''
             OR City IS NULL OR City = ''
          )
        ORDER BY KennelName
        """
    )
    rows = cur.fetchall()
    print(f"to search: {len(rows)}")
    updated = searched = 0
    with DDGS() as ddgs:
        for bid, kennel, owner, city, website, email, phone in rows:
            q = f'"{kennel}" "Jack Russell"'
            if owner and len(str(owner)) > 4 and "@" not in str(owner) and "<" not in str(owner):
                q += f' "{str(owner).split("/")[0].strip()}"'
            try:
                results = list(ddgs.text(q, max_results=8))
            except Exception as e:
                print(f"  fail {kennel}: {e}")
                time.sleep(2)
                continue
            searched += 1
            facts = facts_from_results(kennel, results)
            if not facts:
                if searched % 50 == 0:
                    print(f"  progress {searched}/{len(rows)} updated={updated}")
                time.sleep(0.5)
                continue
            before = (website, email, phone, city)
            apply_web_facts(cur, bid, facts)
            cur.execute(
                "SELECT Website, Email, Phone, City FROM sResults.Breeder WHERE BreederID=?",
                bid,
            )
            after = cur.fetchone()
            if after != before:
                updated += 1
                print(f"  +{bid} {kennel}: {facts}")
                conn.commit()
            if searched % 50 == 0:
                print(f"  progress {searched}/{len(rows)} updated={updated}")
            time.sleep(0.55)
    conn.commit()
    print(f"DONE searched={searched} updated={updated}")


if __name__ == "__main__":
    main()
